function monitor(){return `<h1>Live monitoring</h1><p class="mu">CS-301-MID · Distributed Systems</p><div class="grid g2" style="margin-top:16px"><div class="card col"><h3>Active attempts</h3>${att.map(a=>`<div><div class="row sp"><b>${a.n}</b><span class="pill ${a.st=="Active"?"ok":"in"}">${a.st}</span></div><div class="bar"><i style="width:${a.p/a.of*100}%"></i></div><span class="mu sm">${a.p}/${a.of} answered</span></div>`).join("")}</div>
<div class="card col"><h3>Incidents for review</h3><p class="mu sm">Indicators are context, never conclusive evidence of misconduct.</p>${inc.map(i=>`<div class="row sp sm"><span><b>${i.n}</b> — ${i.e}</span><span class="mu">${i.t}</span></div>`).join("")}</div>
<div class="card col"><h3>Announce to candidates</h3><textarea id="an" rows="2" placeholder="e.g. 10 minutes remaining"></textarea><button class="btn" onclick="if($('#an').value.trim()){ann.unshift($('#an').value);toast('Announcement sent');$('#an').value=''}">Send announcement</button></div></div>`}
function grade(){const w=[{n:"Hira Khan",q:qbank[4],a:"Replicas converge over time if no new writes arrive, e.g. DynamoDB or DNS."},{n:"Bilal Ahmed",q:qbank[5],a:"If W+R is greater than N, read and write sets overlap, so a read sees the latest write."}];return `<h1>Grading</h1><p class="mu" style="margin:4px 0 16px">Objective answers are auto-graded. Written answers need your marks.</p><div class="col">${w.map((x,i)=>`<div class="card col"><div class="row sp"><b>${x.n}</b><span class="pill gr">${x.q.m} marks max</span></div><p class="mu sm">${x.q.t}</p><p>${x.a}</p><div class="row"><input type="number" id="g${i}" placeholder="Marks" style="width:110px"><button class="btn s" onclick="const v=+$('#g${i}').value;if(isNaN(v)||v<0||v>${x.q.m}||$('#g${i}').value==='')return toast('Marks must be between 0 and ${x.q.m}');toast('Graded')">Save grade</button></div></div>`).join("")}<div class="card row sp"><div><b>Ready to publish?</b><p class="mu sm">Review results first. Publishing makes scores visible to candidates.</p></div><button class="btn" onclick="toast('Results published')">Publish results</button></div></div>`}
function analytics(){return `<h1>Question analytics</h1><p class="mu" style="margin:4px 0 16px">Built from actual submissions for CS-301-MID.</p><div class="grid g3" style="margin-bottom:18px"><div class="stat"><b>21.4 / 30</b>Average score</div><div class="stat"><b>83%</b>Pass rate</div><div class="stat"><b>38 min</b>Median time</div></div><div class="card tw"><table><tr><th>Question</th><th style="width:30%">Correct</th><th>Skipped</th><th>Observed</th></tr>${Q.map((q,i)=>`<tr><td>Q${i+1}. ${E(q.t.slice(0,60))}…</td><td><div class="bar"><i style="width:${q.ok}%"></i></div><span class="sm mu">${q.ok}%</span></td><td>${q.sk}%</td><td><span class="pill ${q.ok>70?"ok":q.ok>45?"wn":"er"}">${q.ok>70?"Easy":q.ok>45?"Moderate":"Difficult"}</span>${q.sk>20?` <span class="pill gr">Often skipped</span>`:""}</td></tr>`).join("")}</table></div>`}
function disp(){return `<h1>Dispute resolution</h1><p class="mu" style="margin:4px 0 16px">Every decision is recorded with a reason. Original scores stay visible in the audit trail.</p><div class="col">${disputes.map(d=>`<div class="card row sp"><div><b>${d.n}</b> · <span class="mu">${d.ex}</span><p class="sm">${E(d.why)}</p></div>${d.st=="Open"?`<div class="row"><button class="btn s" onclick="rs(${d.id},'Upheld')">Uphold</button><button class="btn g s" onclick="rs(${d.id},'Rejected')">Reject</button></div>`:`<span class="pill ${d.st=="Upheld"?"ok":"er"}">${d.st}</span>`}</div>`).join("")||'<div class="card mu">No disputes.</div>'}</div>`}
function rs(id,s){const r=prompt("Reason for decision (required):");if(!r||r.length<5)return toast("A reason is required");disputes.find(d=>d.id==id).st=s;R()}
